import { Order, OrderState } from '../domain/Order';
import { OrderItem } from '../domain/OrderItem';
import { Catalogue } from '../domain/Catalogue';

export class OrderService {
  private orders: Map<string, Order> = new Map();
  private orderCounter = 0;

  constructor(private catalogue: Catalogue) {}

  createOrder(items: Array<{ productId: string; quantity: number }>): Order {
    // Validate products exist and check stock
    for (const item of items) {
      const product = this.catalogue.getProduct(item.productId);
      if (!product) {
        throw new Error(`Product ${item.productId} not found`);
      }
      if (!this.catalogue.hasStock(item.productId, item.quantity)) {
        throw new Error(`Insufficient stock for product ${item.productId}`);
      }
    }

    // Reserve stock for all items
    for (const item of items) {
      this.catalogue.reserve(item.productId, item.quantity);
    }

    // Create order
    const orderId = `ORDER-${++this.orderCounter}`;
    const orderItems: OrderItem[] = items.map(item => ({
      productId: item.productId,
      quantity: item.quantity,
      price: this.catalogue.getProduct(item.productId)!.price,
    }));

    const order = new Order(orderId, orderItems);
    this.orders.set(orderId, order);
    return order;
  }

  getOrder(orderId: string): Order | undefined {
    return this.orders.get(orderId);
  }

  getOrdersByState(state: OrderState): Order[] {
    return Array.from(this.orders.values()).filter(order => order.state === state);
  }

  getAllOrders(): Order[] {
    return Array.from(this.orders.values());
  }

  transitionOrder(orderId: string, nextState: OrderState): Order {
    const order = this.orders.get(orderId);
    if (!order) {
      throw new Error(`Order ${orderId} not found`);
    }

    order.transitionTo(nextState);
    return order;
  }

  cancelOrder(orderId: string): Order {
    const order = this.orders.get(orderId);
    if (!order) {
      throw new Error(`Order ${orderId} not found`);
    }

    if (!order.canBeCancelled()) {
      throw new Error(`Order ${orderId} cannot be cancelled in state ${order.state}`);
    }

    // Release reserved stock
    for (const item of order.items) {
      this.catalogue.releaseReservation(item.productId, item.quantity);
    }

    order.state = 'placed'; // Mark as cancelled conceptually
    return order;
  }
}

